import{_ as p,o as a,c as e,ae as t}from"./chunks/framework.BrEqZt6s.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/중철 맹자 순자.md","filePath":"philosophy/중철 맹자 순자.md"}'),b={name:"philosophy/중철 맹자 순자.md"};function o(_,r,i,l,s,n){return a(),e("div",null,[...r[0]||(r[0]=[t('<h2 id="맹자" tabindex="-1">맹자 <a class="header-anchor" href="#맹자" aria-label="Permalink to &quot;맹자&quot;">​</a></h2><p>맹자는 어떤 인물인가<br> 일화, 시대적 배경, 문제의식<br> 중심개념은 무엇인가<br> 덕치, 성선설, 역성혁명론<br> 이상적 인간형<br> 군자<br> 이상적 정치<br> 덕치</p><p>문제의식<br> 전국시대의 혼란한 상황 해결</p><p>인자 무적<br> 덕치 = 인치 = 왕도</p><p>사람은 누구나 불인인지심을 가짐<br> (타인의 고통이나 불행을 보고 차마 그대로 넘어가지 못하는 마음 )<br> 어린 아이가 우물로 기어가는 모습을 본다면 그 누구라도 차마 넘어가지 못할 것이다<br> 측은지심, 수오지심, 사양지심, 시비지심이 각각 인의예지의 단서이다</p><p>이러한 사단은 성선설의 근거</p><p>왜 사람은 타락하는가</p><ol><li>시스템의 미비: 무항산, 무항심</li><li>수양의 무족: 본성을 잘 실행할 수 있도록 호연지기를 길러라</li></ol><p>역성혁명: 왕이 왕답지 못하면 교체해야 한다<br> 공자의 정명론. 군군신신부부자자</p><hr><p>맹자<br> 올바름의 기준을 본성에서 찾음<br> 인간의 본성이 선하기 때문</p><p>순자는 내면에서 찾을 수 없음<br> 선의 가능성을 지니고 있지 않기 때문에<br> 따라서 덕치로 다스릴 수 없고 이떄문에 그 기준을 만들어야하나다<br> 똑똑한 사람이 예를 지정하여 이를 따르자</p><h2 id="순자" tabindex="-1">순자 <a class="header-anchor" href="#순자" aria-label="Permalink to &quot;순자&quot;">​</a></h2><p>문제의식<br> 혼란스러운 사회상황에 대해서 인간을 도덕적 존재로 만들어 극복하려고 함<br> 인간의 본성이 악하기 떄문에 이를 예를 통해 교화<br> -&gt; 예치 정치, 성악설</p><p>천인지분<br> 하늘은 아무런 의지 없는 자연법칙임<br> 초월적 존재 부정</p><p>인간의 본성은 악하기 떄문에 혼란이 생김<br> 예의와 법도는 성인의 실천으로 생기는 것</p><p>예의 존재 이유<br> 욕망과 그 대상이 균형을 이루도록 함<br> 물건은 욕망의 대상, 욕망이 있을 떄 적절히 절제</p><p>자연상태의 인간은 욕망추구적 존재인데, 이러한 욕망의 대상인 재화가 부족.<br> 다툼이 일어나고 이는 공동체의 붕괴를 발생기킨다</p><p>이러한 문제로 인핸 예의 본질은 구별, 구분이다<br> 예에 따라 욕망실현의 방식이 구분됨</p><p>형벌이 죄에 합당하게 이뤄지면 권위, 그렇지 않으면 가벼히 여기게됨</p><p>군주: 예와 법을 잘 아는 자<br> 백성을 인간답게 만들어 줄 수 있는 자.<br> 선왕도 좋지만, 현재적 상황에 맞는 후왕 강조</p>',21)])])}const d=p(b,[["render",o]]);export{c as __pageData,d as default};
